"""Tick-normalized completed-candle profile for Step research."""
import pandas as pd
from analysis.step_sequence_analyzer import analyze_step_sequence
def build_step_market_profile(candles,tick_size):
    rows=candles.copy() if candles is not None else pd.DataFrame();rows=rows[rows.complete.astype(bool)] if "complete" in rows else rows;base={"tick_size":tick_size,"atr_ticks":None,"median_range_ticks":None,"average_run_length":None,"median_run_length":None,"average_pullback_ticks":None,"average_pullback_atr":None,"directional_efficiency":None,"trend_persistence":None,"range_stability":None,"compression_ratio":None,"expansion_ratio":None,"boundary_reaction_frequency":None,"false_break_frequency":None,"sample_size":len(rows),"quality":"insufficient"}
    if not tick_size or tick_size<=0 or len(rows)<20:return base
    ranges=rows.high-rows.low;changes=rows.close.diff().dropna();path=float(changes.abs().sum());atr=float(ranges.tail(14).mean());sequence=analyze_step_sequence(rows);pullbacks=changes[changes*changes.tail(20).sum()<0].abs();long=float(ranges.tail(min(100,len(rows))).mean());recent=float(ranges.tail(10).mean());stability=max(0,min(1,1-float(ranges.std())/max(float(ranges.mean()),tick_size)))
    return {**base,"atr_ticks":atr/tick_size,"median_range_ticks":float(ranges.median())/tick_size,"average_range_ticks":float(ranges.mean())/tick_size,"average_run_length":sequence["average_sequence_length"],"median_run_length":sequence["average_sequence_length"],"average_pullback_ticks":float(pullbacks.mean())/tick_size if len(pullbacks) else 0,"average_pullback_atr":float(pullbacks.mean())/atr if len(pullbacks) and atr else 0,"directional_efficiency":abs(float(rows.close.iloc[-1]-rows.close.iloc[0]))/path if path else 0,"trend_persistence":float((changes>0).mean()) if changes.sum()>=0 else float((changes<0).mean()),"range_stability":stability,"compression_ratio":recent/max(long,tick_size),"expansion_ratio":float(ranges.tail(3).mean())/max(long,tick_size),"sample_size":len(rows),"quality":"good" if len(rows)>=200 else "partial"}
